import * as React from 'react';
import { cleanup, render, screen, fireEvent } from '@testing-library/react';
import {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuItem,
} from './dropdown-menu';
import { describe, it, expect, vi, afterEach } from 'vitest';

describe('temp: DropdownMenuTrigger ref identity', () => {
  afterEach(cleanup);

  it('stable user ref is not re-invoked when the menu opens/closes', async () => {
    const handleRef = vi.fn();
    render(
      <DropdownMenu>
        <DropdownMenuTrigger ref={handleRef}>Open</DropdownMenuTrigger>
        <DropdownMenuContent>
          <DropdownMenuItem>Item</DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>,
    );

    const trigger = screen.getByRole('button', { name: 'Open' });
    const callsAtMount = handleRef.mock.calls.length;
    const mountArg = handleRef.mock.calls.at(-1)![0];
    expect(callsAtMount).toBe(1);
    expect(mountArg).toBe(trigger);

    fireEvent.click(trigger);
    const item = await screen.findByRole('menuitem');
    fireEvent.click(item); // closes the menu, re-rendering the trigger

    console.log('REF-CHECK total calls after open/close:', handleRef.mock.calls.length);
    expect(handleRef).toHaveBeenCalledTimes(1);
  });
});

