import * as React from 'react';
import { cleanup, render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuItem,
} from './dropdown-menu';
import { describe, it, expect, vi, afterEach } from 'vitest';

describe('temp: DropdownMenuTrigger ref identity', () => {
  afterEach(cleanup);

  it('stable user ref is not re-invoked when the menu opens/closes', async () => {
    const handleRef = vi.fn();
    render(
      <DropdownMenu>
        <DropdownMenuTrigger ref={handleRef}>Open</DropdownMenuTrigger>
        <DropdownMenuContent>
          <DropdownMenuItem>Item</DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>,
    );

    const trigger = screen.getByRole('button', { name: 'Open' });
    expect(handleRef).toHaveBeenCalledTimes(1);
    expect(handleRef).toHaveBeenLastCalledWith(trigger);

    await userEvent.click(trigger);
    const item = await screen.findByRole('menuitem');
    expect(handleRef).toHaveBeenCalledTimes(1); // re-render after opening must not re-invoke

    await userEvent.click(item); // closes the menu
    await screen.findByRole('button', { name: 'Open' });
    expect(handleRef.mock.calls.length).toBe(1);
  });
});

