import * as React from 'react';
import { cleanup, render, screen, fireEvent } from '@testing-library/react';
import {
  Menu,
  MenuContent,
  MenuSub,
  MenuSubTrigger,
  MenuSubContent,
  MenuItem,
} from './menu';
import { describe, it, expect, vi, afterEach } from 'vitest';

describe('temp: MenuSubTrigger ref identity', () => {
  afterEach(cleanup);

  it('stable user ref is not re-invoked when the sub menu opens', () => {
    const subRef = vi.fn();
    const [open, setOpen] = React.useState(true);
    render(
      <Menu open={open} onOpenChange={setOpen}>
        <MenuContent>
          <MenuSub>
            <MenuSubTrigger ref={subRef}>Sub</MenuSubTrigger>
            <MenuSubContent>
              <MenuItem>SubItem</MenuItem>
            </MenuSubContent>
          </MenuSub>
          <MenuItem>Item</MenuItem>
        </MenuContent>
      </Menu>,
    );

    const subTrigger = screen.getByRole('menuitem', { name: 'Sub' });
    expect(subRef).toHaveBeenCalledTimes(1);
    expect(subRef).toHaveBeenLastCalledWith(subTrigger);

    fireEvent.click(subTrigger); // opens the sub menu, re-rendering the trigger
    const subItem = screen.getByRole('menuitem', { name: 'SubItem' });
    expect(subItem).toBeTruthy();
    expect(subRef.mock.calls.length).toBe(1);
  });
});

