import * as React from 'react';
import { cleanup, render, screen, fireEvent } from '@testing-library/react';
import {
  Menu,
  MenuContent,
  MenuSub,
  MenuSubTrigger,
  MenuSubContent,
  MenuItem,
} from './menu';
import { describe, it, expect, vi, afterEach } from 'vitest';

describe('temp: MenuSubTrigger ref identity', () => {
  afterEach(cleanup);

  it('stable user ref is not re-invoked on unrelated re-renders', () => {
    const subRef = vi.fn();
    const Harness = () => {
      const [tick, setTick] = React.useState(0);
      return (
        <div data-tick={tick}>
          <button onClick={() => setTick((t) => t + 1)}>tick</button>
          <Menu open onOpenChange={() => {}}>
            <MenuContent>
              <MenuSub>
                <MenuSubTrigger ref={subRef}>Sub</MenuSubTrigger>
                <MenuSubContent>
                  <MenuItem>SubItem</MenuItem>
                </MenuSubContent>
              </MenuSub>
              <MenuItem>Item</MenuItem>
            </MenuContent>
          </Menu>
        </div>
      );
    };

    render(<Harness />);

    const subTrigger = screen.getByRole('menuitem', { name: 'Sub' });
    expect(subRef).toHaveBeenCalledTimes(1);
    expect(subRef).toHaveBeenLastCalledWith(subTrigger);

    fireEvent.click(screen.getByRole('button', { name: 'tick' }));
    expect(subRef.mock.calls.length).toBe(1);
  });
});
